    await client.query(`ALTER TABLE listings ADD COLUMN IF NOT EXISTS status TEXT DEFAULT 'active';`);
    await client.query(`ALTER TABLE listings ADD COLUMN IF NOT EXISTS is_published BOOLEAN DEFAULT true;`);

